import React from 'react'
import "./NavBar.css";
import logo from "../../Assets/logo.png";

const NavBar = () => {
  return (
    <nav className='container'>
        <img src={logo} alt='' className='logo'/>
        <ul>
            <li>Home</li>
            <li>Program</li>
            <li>About us</li>
            <li>Testimonials</li>
            <li>Contact us</li>
        </ul>
    </nav>
  )
}

export default NavBar;
